#[test]fn bq044_attachment_choice_and_game_room_corruption_rejected(){let mut g=offered();let host=field(&mut g,"JC125",2);let c=g.make_card("JC073",2);let id=c.id.clone();g.attachments.push(Attachment{card:c,host_id:host});let hidden=field(&mut g,"JC125",2);g.board_mut(&hidden).unwrap().face_down=true;choose(&mut g,vec!["accept".into()]);crate::jc029_tests::pass_top(&mut g);choose(&mut g,vec!["p2".into()]);assert!(!g.pending.as_ref().unwrap().choice.options.iter().any(|o|o.id==hidden));let room=crate::jc029_tests::envelope(&g);let restored=crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&room).unwrap()).unwrap();assert_eq!(serde_json::to_value(&restored.game).unwrap(),serde_json::to_value(&g).unwrap());for n in 0..3{let mut bad=room.clone();if n==0{bad.game.pending.as_mut().unwrap().seat=3;}else{let ChoiceResolution::Frame{frame,..}=&mut bad.game.pending.as_mut().unwrap().resolution else{panic!()};if n==1{frame.already_paid.clear();}else{bad.game.effects.push_back(Effect::Frame{frame:frame.clone()});}}assert!(Game::from_persisted(&serde_json::to_string(&bad.game).unwrap()).is_err());assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());}let p=g.pending.clone().unwrap();reject(&mut g,2,Action{choice_id:Some(p.choice.id),selected:Some(vec![id.clone()]),amount:Some(1),..Action::new("choose")});choose(&mut g,vec![id.clone()]);assert!(!g.attachments.iter().any(|a|a.card.id==id));restore(&mut g);}
#[test]fn bq044_real_spell_room_commands_duplicate_and_restore(){use crate::abi112_review_play_tests::Trace;let mut g=game();field(&mut g,"BQ044",0);let dead=field(&mut g,"JC125",0);let enemy=field(&mut g,"JC125",2);fund(&mut g,0,"JC096",2);fund(&mut g,0,"JC049",3);let spell=held(&mut g,"JZ54",0);let mut t=Trace::new_preserving_rng(g,"bq044-prepared-real-spell-sacrifice-trigger".into(),944);t.action(0,Action{card_id:Some(spell),target_id:Some("p0".into()),..Action::new("play")});t.until_pending();t.choose(vec![dead]);t.until_pending();assert!(matches!(&t.room.game.pending.as_ref().unwrap().resolution,ChoiceResolution::Declare{declaration:d,..}if d.ability.key==crate::bq044::KEY));t.choose(vec!["accept".into()]);t.until_pending();t.choose(vec!["p2".into()]);t.choose(vec![enemy.clone()]);assert!(t.room.game.board(&enemy).is_none()&&t.room.game.pending.is_none()&&t.room.game.stack.is_empty());let mut value=t.value();for s in value["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let result=r.transition(s["seat"].as_u64().unwrap() as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert_eq!(result.outcome,"rejected");assert_eq!(result.state,s["expected"]["state"]);assert!(!result.changed&&result.journal.is_empty());s["duplicate"]=serde_json::to_value(result).unwrap();}if let Ok(path)=std::env::var("BQ044_NATIVE_OUT"){std::fs::write(path,serde_json::to_vec(&value).unwrap()).unwrap();}}
#[test]fn bq044_simultaneous_self_and_other_sacrifice_and_no_funds(){let mut g=game();let source=field(&mut g,"BQ044",0);let other=field(&mut g,"JC125",0);let wave=[source,other].into_iter().map(|id|{let(r,c)=g.board(&id).unwrap();let s=g.source_snapshot(c,Some(r));(id,RemovalCause::Sacrifice,s)}).collect();g.remove_death_batch(wave);assert_eq!(count(&g),2);restore(&mut g);g.drive().unwrap();assert!(g.pending.is_none()&&g.stack.is_empty());restore(&mut g);}
#[test]fn bq044_nested_or_transplanted_program_is_rejected(){use crate::rules::*;let mut a=crate::bq044::definition().abilities.remove(0);a.ops=vec![Op::ForEachLivingPlayer(a.ops.clone())];assert!(crate::bq044::related(&a));assert!(validate_ability("BQ044",&a).is_err());a.key="foreign".into();a.event=None;assert!(validate_ability("JC125",&a).is_err());let mut ds=definitions().clone();ds.insert("JC125".into(),with_abilities(vec![a]));assert!(validate_definitions(&ds).is_err());}
fn core(parked:bool)->(Game,String){let mut g=game();g.players[0].society_zone.card=Some(g.make_card("MSBQ02",0));let c=g.make_card("BQ044",0);let id=c.id.clone();g.core_zones.push(crate::core_zone::CoreZone{owner:0,definition:"BQ044".into(),card:parked.then(||c.clone()),rest:0});if !parked{g.regions[0].cards.push(c);}fund(&mut g,0,"JC049",8);fund(&mut g,0,"JC069",1);(g,id)}
fn core_command(g:&mut Game,id:&str){let spell=held(g,id,0);act(g,0,Action{card_id:Some(spell),option:Some("core".into()),..Action::new("play")});for _ in 0..64{if g.pending.is_some(){return}pass(g);}panic!("no core pending");}
fn core_finish(g:&mut Game){for _ in 0..128{if let Some(p)=g.pending.clone(){choose(g,p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect());}else if g.stack.is_empty()&&g.effects.is_empty(){return}else{pass(g);}}panic!("core unfinished");}
#[test]fn bq044_core_both_zones_sacrifice_draw_repress(){for parked in [true,false]{let(mut g,_)=core(parked);let victim=field(&mut g,"JC125",0);g.regions[0].influence[1]=2;core_command(&mut g,"BQ048");let hand=g.players[0].hand.len();assert_eq!(g.pending.as_ref().unwrap().choice.kind,"bq044-core-sacrifice");choose(&mut g,vec![victim.clone()]);core_finish(&mut g);assert_eq!(g.players[0].hand.len(),hand+1);assert!(g.board(&victim).is_none());assert_eq!(g.regions[0].influence[1],1);restore(&mut g);}}
#[test]fn bq044_core_self_departure_returns_before_draw(){let(mut g,id)=core(false);core_command(&mut g,"BQ048");let hand=g.players[0].hand.len();choose(&mut g,vec![id]);assert_eq!(g.players[0].hand.len(),hand);if g.pending.as_ref().is_some_and(|p|p.choice.kind=="trigger"){choose(&mut g,vec![]);}assert_eq!(g.pending.as_ref().unwrap().choice.kind,"core-return");assert_eq!(g.players[0].hand.len(),hand);restore(&mut g);choose(&mut g,vec!["core".into()]);core_finish(&mut g);assert_eq!(g.players[0].hand.len(),hand+1);assert_eq!(g.core_zones[0].rest,1);assert!(g.core_zones[0].card.is_some());}
#[test]fn bq044_core_two_invocations_keep_original_parent_and_no_victim_has_no_benefit(){let(mut g,_)=core(true);field(&mut g,"JC125",0);field(&mut g,"JC125",0);g.regions[0].influence[1]=4;core_command(&mut g,"BQ063");let hand=g.players[0].hand.len();core_finish(&mut g);assert_eq!(g.players[0].hand.len(),hand+2);assert_eq!(g.regions[0].influence[1],1);let(mut g,_)=core(true);let s=held(&mut g,"BQ048",0);let hand=g.players[0].hand.len();act(&mut g,0,Action{card_id:Some(s),option:Some("core".into()),..Action::new("play")});core_finish(&mut g);assert_eq!(g.players[0].hand.len(),hand-1);}
#[test]fn bq044_core_xg25_response_holds_draw_and_restores(){let(mut g,_)=core(true);g.players[0].society_zone.secrecy=1;let ghost=field(&mut g,"XG25",0);let host=field(&mut g,"JC125",2);core_command(&mut g,"BQ048");let hand=g.players[0].hand.len();choose(&mut g,vec![ghost]);assert_eq!(g.players[0].hand.len(),hand);assert!(matches!(g.pending.as_ref().unwrap().resolution,ChoiceResolution::Declare{..}));let room=crate::jc029_tests::envelope(&g);g=crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&room).unwrap()).unwrap().game;choose(&mut g,vec![host]);assert_eq!(g.players[0].hand.len(),hand);core_finish(&mut g);assert_eq!(g.players[0].hand.len(),hand+1);assert!(g.sealed_cards.iter().any(|s|s.card.definition=="XG25"));}
#[test]fn bq044_core_pending_corruption_and_extra_payload_reject(){let(mut g,_)=core(true);let id=field(&mut g,"JC125",0);core_command(&mut g,"BQ048");for n in 0..4{let mut bad=g.clone();let ChoiceResolution::Frame{frame,choice:FrameChoice::BQ044Core(s)}=&mut bad.pending.as_mut().unwrap().resolution else{panic!()};match n{0=>s.core.card.definition="BQ046".into(),1=>frame.source.card.definition="JC001".into(),2=>bad.effects.push_back(Effect::Frame{frame:frame.clone()}),_=>bad.pending.as_mut().unwrap().choice.options.clear()};assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());let mut room=crate::jc029_tests::envelope(&g);room.game=bad;assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&room).unwrap()).is_err());}let p=g.pending.clone().unwrap();reject(&mut g,0,Action{choice_id:Some(p.choice.id),selected:Some(vec![id]),amount:Some(9),..Action::new("choose")});}
fn trace_value(t:crate::abi112_review_play_tests::Trace)->serde_json::Value{let mut v=t.value();for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let d=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert_eq!(d.outcome,"rejected");assert_eq!(d.state,s["expected"]["state"]);s["duplicate"]=serde_json::to_value(d).unwrap();}v}
fn trace_finish(t:&mut crate::abi112_review_play_tests::Trace){for _ in 0..128{if let Some(p)=t.room.game.pending.clone(){t.choose(p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect());}else if t.room.game.pending.is_none()&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){return}else{t.pass();}}panic!("unfinished trace");}
