#[test]fn bq044_core_natural_and_prepared_room_export(){use crate::abi112_review_play_tests::Trace;let mut cases=vec![natural()];for(id,n)in[("BQ048",946),("BQ063",947)]{let(mut g,_)=core(true);field(&mut g,"JC125",0);field(&mut g,"JC125",0);g.regions[0].influence[1]=4;let spell=held(&mut g,id,0);let mut t=Trace::new_preserving_rng(g,format!("bq044-prepared-{id}-core"),n);t.action(0,Action{card_id:Some(spell),option:Some("core".into()),..Action::new("play")});trace_finish(&mut t);cases.push(trace_value(t));}let(mut g,_)=core(true);g.players[0].society_zone.secrecy=1;let ghost=field(&mut g,"XG25",0);let host=field(&mut g,"JC125",2);let spell=held(&mut g,"BQ048",0);let mut t=Trace::new_preserving_rng(g,"bq044-prepared-xg25-response-and-core-resume".into(),948);t.action(0,Action{card_id:Some(spell),option:Some("core".into()),..Action::new("play")});t.until_pending();t.choose(vec![ghost]);t.until_pending();t.choose(vec![host]);trace_finish(&mut t);assert!(t.room.game.sealed_cards.iter().any(|s|s.card.definition=="XG25"));cases.push(trace_value(t));if let Ok(path)=std::env::var("BQ044_CORE_OUT"){let mut bindings=crate::bq052_tests::source_bindings();use sha2::{Digest,Sha256};for(n,b)in[("rust-game/src/bq044.rs",include_bytes!("bq044.rs").as_slice()),("rust-game/src/bq044_core.rs",include_bytes!("bq044_core.rs").as_slice()),("rust-game/src/bq044_tests.rs",include_bytes!("bq044_tests.rs").as_slice())]{bindings["files"][n]=format!("{:x}",Sha256::digest(b)).into();}std::fs::write(path,serde_json::to_vec(&serde_json::json!({"catalog":crate::catalog::catalog(),"sourceBindings":bindings,"cases":cases})).unwrap()).unwrap();}}
#[test]fn bq044_core_generated_victim_disappears_without_entity_grave_card(){let(mut g,_)=core(true);let id=field(&mut g,"TK010",0);core_command(&mut g,"BQ048");let hand=g.players[0].hand.len();choose(&mut g,vec![id.clone()]);core_finish(&mut g);assert_eq!(g.players[0].hand.len(),hand+1);assert!(g.board(&id).is_none());assert!(!g.players.iter().any(|p|p.graveyard.iter().chain(&p.hand).chain(&p.deck).any(|c|c.definition=="TK010")));restore(&mut g);}
